/*
    analyzenotefrequency settings:
    use OUTER_CYCLES = 32, min detectable frequency will be ~30Hz @ fs = 1kHz (must be a full cycle offset).
    SAMPLES_TO_ANALYZE >= 200 to get real-world measurement +/- a couple Hz.

    compressor data:
    80% and 90% are hardest to measure, have lowest probabilities (~0.6).
    use threshold = 0.7 to get initial data, but could dial this back in future.

    biquad IIR settings:
    q = 3, fc = 70, gain *20. reasonable compromise that means we're measuring compressor signal and not filter ringing

    IIR impulse responses for reference:
    fc = 70 Hz, tc = 14ms, cycles in 100ms = 7
    q = 3, cycle 1 magnitude normalized to 1, cycle 2 = 0.36, 3 = 0.13
    q = 6 2 = 0.6 3 = 0.36
    q = 10 2 = 0.73 3 = 0.53
*/

